-- 0016_padroniza_telefones.sql
-- Padroniza TODOS os telefones legados para o formato unico BR: armazena so
-- digitos (10 = fixo, 11 = celular). A exibicao/exportacao formata para
-- (DD) 9XXXX-XXXX ou (DD) XXXX-XXXX (feito no app).
--
-- Regras desta migration (casam com telDigitos/telValido do index.ts):
--   * remove separadores comuns (espaco, ( ) - . +, nbsp, tab) e o DDI 55;
--   * so grava o resultado quando ele fica com 10 ou 11 digitos EXATOS e
--     100% numericos (guard GLOB). Qualquer coisa fora disso (incompleto,
--     com ramal, dois numeros, letras) e PRESERVADA como esta, para revisao
--     manual -- nada se perde.
--   * idempotente: numeros ja em digitos nao mudam (a clausula final `col <> D`
--     evita regravar o mesmo valor). Seguro re-aplicar.

-- empresas.telefone_comercial
UPDATE empresas SET telefone_comercial = CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END
WHERE telefone_comercial IS NOT NULL AND telefone_comercial <> ''
  AND length(CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END) IN (10,11)
  AND NOT ((CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END) GLOB '*[^0-9]*')
  AND telefone_comercial <> (CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone_comercial,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END);

