  AND NOT ((CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END) GLOB '*[^0-9]*')
  AND whatsapp <> (CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(whatsapp,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END);

