-- filiais.telefone
UPDATE filiais SET telefone = CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END
WHERE telefone IS NOT NULL AND telefone <> ''
  AND length(CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END) IN (10,11)
  AND NOT ((CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END) GLOB '*[^0-9]*')
  AND telefone <> (CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'')) IN (12,13) AND substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),1,2)='55' THEN substr(replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),''),3) ELSE replace(replace(replace(replace(replace(replace(replace(replace(telefone,' ',''),'(',''),')',''),'-',''),'.',''),'+',''),char(160),''),char(9),'') END);
